  "status": "implemented",
  "summary": "Implemented the `Observation.map` method in `Observation.java` to preserve status and detail, apply the mapper exactly once for available data, and handle null mapper or null mapped result correctly.",
  "edits": [
    {
      "path": "src/main/java/dev/atmcompanion/state/Observation.java",
      "operation": "replace",
      "find": "public static <T> Observation<T> notIntegrated(String reason) {",
      "replace": "public static <T> Observation<T> notIntegrated(String reason) {
    return new Observation<>(CapabilityStatus.NOT_INTEGRATED, null, reason);
}

    public <U> Observation<U> map(java.util.function.Function<? super T, ? extends U> mapper) {
        if (mapper == null) {
            throw new IllegalArgumentException("Mapper cannot be null");
        }
        if (this.status != CapabilityStatus.AVAILABLE) {
            return new Observation<>(this.status, null, this.detail);
        }
        U mappedData = mapper.apply(this.data);
        if (mappedData == null) {
            throw new IllegalArgumentException("Mapped result cannot be null");
        }
        return new Observation<>(CapabilityStatus.AVAILABLE, mappedData, this.detail);
    }"
    }
